package main

import("encoding/json";"fmt";"html/template";"net/http";"os";"path/filepath";"strings";"sync";"time")
type item struct{ID string `json:"id"`;Name string `json:"name"`}
type server struct{path string;mu sync.Mutex;failed map[string]bool}
func main(){path:=os.Getenv("TENE_REFERENCE_STATE");if path==""{path=filepath.Join(os.TempDir(),"tene-reference-state.json")};s:=&server{path:path,failed:map[string]bool{}};mux:=http.NewServeMux();mux.HandleFunc("/",s.page);mux.HandleFunc("/api/items",s.items);mux.HandleFunc("/api/state",s.state);addr:=os.Getenv("TENE_REFERENCE_ADDR");if addr==""{addr="127.0.0.1:4173"};fmt.Printf("reference web listening on %s\n",addr);if err:=http.ListenAndServe(addr,mux);err!=nil{panic(err)}}
func(s *server)page(w http.ResponseWriter,r *http.Request){if r.URL.Path!="/"{http.NotFound(w,r);return};w.Header().Set("Content-Type","text/html; charset=utf-8");template.Must(template.New("page").Parse(pageHTML)).Execute(w,nil)}
func(s *server)items(w http.ResponseWriter,r *http.Request){if r.Method==http.MethodDelete{s.mu.Lock();defer s.mu.Unlock();os.Remove(s.path);s.failed=map[string]bool{};w.WriteHeader(204);return};if r.Method!=http.MethodPost{http.Error(w,"method not allowed",405);return};r.Body=http.MaxBytesReader(w,r.Body,4096);var in struct{Name string `json:"name"`;FailOnce bool `json:"fail_once"`};if json.NewDecoder(r.Body).Decode(&in)!=nil||strings.TrimSpace(in.Name)==""{jsonError(w,400,"Name is required");return};s.mu.Lock();defer s.mu.Unlock();if in.FailOnce&&!s.failed[in.Name]{s.failed[in.Name]=true;jsonError(w,503,"Storage is temporarily unavailable. Retry safely.");return};items,err:=s.read();if err!=nil{jsonError(w,500,"State is unavailable");return};created:=item{ID:fmt.Sprintf("item-%d",time.Now().UnixNano()),Name:strings.TrimSpace(in.Name)};items=append(items,created);if err:=os.MkdirAll(filepath.Dir(s.path),0755);err!=nil{jsonError(w,500,"State is unavailable");return};b,_:=json.Marshal(items);if err:=os.WriteFile(s.path,b,0600);err!=nil{jsonError(w,500,"State is unavailable");return};w.Header().Set("Content-Type","application/json");w.WriteHeader(201);json.NewEncoder(w).Encode(created)}
func(s *server)state(w http.ResponseWriter,r *http.Request){s.mu.Lock();defer s.mu.Unlock();items,err:=s.read();if err!=nil{jsonError(w,500,"State is unavailable");return};w.Header().Set("Content-Type","application/json");json.NewEncoder(w).Encode(items)}
func(s *server)read()([]item,error){b,err:=os.ReadFile(s.path);if os.IsNotExist(err){return []item{},nil};if err!=nil{return nil,err};var out []item;if err:=json.Unmarshal(b,&out);err!=nil{return nil,err};return out,nil}
func jsonError(w http.ResponseWriter,status int,message string){w.Header().Set("Content-Type","application/json");w.WriteHeader(status);json.NewEncoder(w).Encode(map[string]string{"error":message})}
const pageHTML=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Tene Journey</title></head><body><main><h1>Create an item</h1><form id="form"><label for="name">Item name</label><input id="name" name="name" required><label><input id="fail" type="checkbox"> Simulate one storage failure</label><button>Create</button></form><p id="status" role="status" aria-live="polite"></p><button id="retry" hidden>Retry</button></main><script>let pending=null;async function submit(){const status=document.querySelector('#status');status.textContent='Saving…';const response=await fetch('/api/items',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(pending)});const body=await response.json();if(!response.ok){status.textContent=body.error;document.querySelector('#retry').hidden=response.status!==503;return}status.textContent='Created '+body.name;document.querySelector('#retry').hidden=true}document.querySelector('#form').addEventListener('submit',e=>{e.preventDefault();const name=document.querySelector('#name').value.trim();if(!name){document.querySelector('#status').textContent='Name is required';return}pending={name,fail_once:document.querySelector('#fail').checked};submit()});document.querySelector('#retry').addEventListener('click',submit);</script></body></html>`
